"""Des annonces fictives et des photos d’illustration pour découvrir le MVP."""
from datetime import datetime, timedelta, timezone


def demo_listings():
    examples = [
        dict(title="Une villa, entre lumière et sérénité", transaction_type="vente", property_type="maison", price=890000, city="La Marsa", district="Gammarth", surface=280, rooms=6, bedrooms=4, images=["villa", "living", "bright"], amenities=["Piscine", "Jardin", "Parking", "Climatisation"], contact_name="Maison & Rivage · Démo", description="Une architecture ouverte sur l’extérieur, de beaux volumes et la douceur d’un jardin méditerranéen. Cette villa offre un vaste séjour, une cuisine équipée et quatre chambres, dont une suite parentale.\n\nÀ l’extérieur, une terrasse et une piscine invitent à profiter des beaux jours. Un garage complète ce bien.\n\nAnnonce fictive destinée à présenter la plateforme. Les photographies sont des illustrations et ne représentent pas un bien réellement proposé à la vente."),
        dict(title="Un appartement qui respire", transaction_type="location", property_type="appartement", price=1850, city="Tunis", district="Les Berges du Lac 2", surface=115, rooms=3, bedrooms=2, images=["living", "interior"], amenities=["Balcon", "Ascenseur", "Parking", "Climatisation"], contact_name="Nadia · Démo", description="Un appartement lumineux aux lignes épurées, idéal pour s’installer dans un quartier vivant et agréable. Le séjour s’ouvre sur un balcon, la cuisine est équipée et les deux chambres disposent de rangements.\n\nRésidence avec ascenseur et place de parking. Loyer mensuel indiqué, hors charges.\n\nCeci est une annonce fictive de démonstration. Les photos sont uniquement illustratives."),
        dict(title="L’esprit méditerranéen, chez vous", transaction_type="vente", property_type="maison", price=675000, city="Hammamet", district="Yasmine Hammamet", surface=210, rooms=5, bedrooms=3, images=["house", "bright", "loft"], amenities=["Terrasse", "Jardin", "Parking"], contact_name="Rivage Immobilier · Démo", description="Une maison accueillante, pensée pour les moments partagés. Ses pièces de vie baignées de lumière se prolongent vers une terrasse et un jardin arboré. À l’étage, trois chambres et une salle de bains.\n\nUn environnement résidentiel, proche des commerces et des promenades.\n\nAnnonce fictive : aucun bien réel n’est proposé. Photographies d’illustration."),
        dict(title="Un cocon au cœur de la ville", transaction_type="location", property_type="appartement", price=1200, city="Sousse", district="Sahloul", surface=82, rooms=3, bedrooms=2, images=["interior", "living"], amenities=["Meublé", "Ascenseur", "Climatisation"], contact_name="Amine · Démo", description="Un intérieur chaleureux et fonctionnel dans une résidence calme. Cet appartement meublé dispose d’un salon confortable, de deux chambres et d’une cuisine ouverte.\n\nÀ proximité des commerces et des transports. Loyer mensuel hors charges.\n\nAnnonce de démonstration, sans offre réelle. Photos d’illustration."),
        dict(title="De l’espace pour tous vos projets", transaction_type="vente", property_type="appartement", price=345000, city="Ariana", district="Ennasr 2", surface=145, rooms=4, bedrooms=3, images=["loft", "bright"], amenities=["Terrasse", "Ascenseur", "Parking"], contact_name="Yasmine · Démo", description="Un bel appartement familial avec des volumes généreux et une agréable terrasse. Il comprend un double séjour, une cuisine indépendante et trois chambres lumineuses.\n\nRésidence avec ascenseur et parking, dans un quartier proche des services du quotidien.\n\nCette annonce est fictive et les photographies sont illustratives."),
        dict(title="La mer pour horizon", transaction_type="location", property_type="maison", price=3200, city="La Marsa", district="Sidi Daoud", surface=185, rooms=5, bedrooms=3, images=["hero", "bright", "interior"], amenities=["Terrasse", "Jardin", "Climatisation", "Parking"], contact_name="Horizon Habitat · Démo", description="Une maison indépendante qui fait la part belle à la lumière et à la vie dehors. Grand séjour, trois chambres et terrasse généreuse pour les soirées d’été.\n\nLocation longue durée. Loyer mensuel hors charges.\n\nAnnonce entièrement fictive de démonstration. Les images sont des photographies d’illustration, pas une représentation du bien."),
    ]
    now = datetime.now(timezone.utc)
    items = []
    for i, example in enumerate(examples):
        example["id"] = f"demo{i + 1:012d}"
        example["images"] = [f"/static/images/{name}.jpg" for name in example["images"]]
        example["contact_email"] = ""
        example["contact_phone"] = ""
        example["created_at"] = (now - timedelta(hours=8 + i * 18)).isoformat()
        items.append(example)
    return items
